class ReconocimientoFacial{
    
        var $sql;
        var $cara;
    
    	function __construct(  ){
            $this->sql=new Conectar();
            $this->cara=new Caras(NAMESPACE_DEFECTO);
        }
        
        function guardar($uid,$tid){
            $letras=["A","B","C","D","E","F","G","H","I","J","K","L","M","N","P","Q","R","S","T","U","V","W","X","Y","Z"];
            $existe=true;
            while($existe){
                $cod=$letras[rand(0, count($letras)-1)];
                for($i=1;$i<=6;$i++){
                    $cod.= rand(0, 9);
                }
                $this->sql->Consultar("usuarios", "id", "cod_interno='".$cod."'",true);
                if($this->sql->num==0){
                    $existe=false;
                }
            }
            if($uid==""){
                $uid=$cod."@".NAMESPACE_DEFECTO;
            }
            $this->sql->Insertar("usuarios", ["uid","cod_interno"], [$uid,$cod],true);
            $user_sql_id=$this->sql->id;
            $this->cara->guarda($cod,$uid,$tid);  
            return $user_sql_id;
        }
        
        
        function acceso($user_id,$camara_id,$fotos){
            $fotos_ids=[];
            for($i=0;$i<count($fotos);$i++){
                $this->sql->Insertar("fotos", ["user_id","nombre"], [$user_id,$fotos[$i]],true);
                $fotos_ids[]=$this->sql->id;
            }
            if(count($fotos)==1){
                $fotos_ids[]=0;
            }
            $this->sql->Insertar("fotos_parejas", ["foto_id1","foto_id2"], [$fotos_ids[0],$fotos_ids[1]],true);
            $fotos_parejas_id=$this->sql->id;
            
            $v_fecha= explode("/", $fotos[0]);
            $hora=$v_fecha[count($v_fecha)-1];
            $v_hora= explode("[", $hora);
            $hora=$v_hora[0];
            for($i=0;$i<count($v_fecha);$i++){
                $cadena= str_split($v_fecha[$i]);
                $count=0;
                for($j=0;$j<count($cadena);$j++){
                    if($cadena[$j]=="-"){
                        $count++;
                    }
                }
                if($count==2){
                    $fecha=$v_fecha[$i];
                }
            }
            $fecha.=" ".$hora;
                    
            $this->sql->Insertar("accesos", ["user_id","camara_id","fotos_parejas_id","fecha_segun_foto"], [$user_id,$camara_id,$fotos_parejas_id,$fecha],true);
            $id_acceso=$this->sql->id;
            
            /*-INI- Control de aforo*/
            $this->sql->Consultar("camaras","*", "id=".$camara_id);
            if($this->sql->row["puerta"]==1 or $this->sql->row["salida"]==1){
                $this->sql->Consultar("locales","aforo,id", "id=".$this->sql->row["local_id"]);
                if($this->sql->row["puerta"]==1){
                    $this->sql->Actualizar("locales", ["aforo"], [$this->sql->row["aforo"]+1], "id=".$this->sql->row["id"]);    
                }else{ //$this->sql->row["salida"]==1
                    $this->sql->Actualizar("locales", ["aforo"], [$this->sql->row["aforo"]-1], "id=".$this->sql->row["id"]);
                }
            }
            /*-FIN- Control de aforo*/
            
            rename("./images/tmps/temp1.jpg", "./images/tmps/".$id_acceso."_1.jpg");
            if($fotos[1]!=""){
                rename("./images/tmps/temp0.jpg", "./images/tmps/".$id_acceso."_0.jpg");    
            }
            
            $this->sql->Actualizar("fotos", ["nombre"], ["./images/tmps/".$id_acceso."_1.jpg"], "id=".$fotos_ids[0],true);
            $this->sql->Actualizar("fotos", ["nombre"], ["./images/tmps/".$id_acceso."_0.jpg"], "id=".$fotos_ids[1],true);
            
            
        }
        
        function user_por_cod_interno($cod){
            echo "user_por_cod_interno:".$cod."\n";
            $this->sql->Consultar("usuarios", "id", "cod_interno='".$cod."'",true);
            echo "Consultado, muestra algo?\n";
            echo "estop es lo k voy a devolver:".$this->sql->row["id"]."\n";
            return $this->sql->row["id"];
        }
        function user_por_uid($uid){
            echo "user_por_uid:".$uid."\n";
            $this->sql->Consultar("usuarios", "id", "uid='".$cod."'",true);
            echo "Consultado, muestra algo?\n";
            echo "estop es lo k voy a devolver:".$this->sql->row["id"]."\n";
            return [$this->sql->row["id"],$this->sql->row["cod_interno"]];
        }
}